// usage.mjs <session.jsonl> — per-agent token breakdown, deduped by message.id
import fs from 'node:fs';
import path from 'node:path';

const main = process.argv[2];
const dir = main.replace(/\.jsonl$/, '');
const files = [{ label: 'main', file: main }];
const subDir = path.join(dir, 'subagents');
if (fs.existsSync(subDir)) {
  for (const f of fs.readdirSync(subDir).filter((x) => x.endsWith('.jsonl'))) {
    let label = f;
    const meta = path.join(subDir, f.replace(/\.jsonl$/, '.meta.json'));
    if (fs.existsSync(meta)) {
      try { label = JSON.parse(fs.readFileSync(meta, 'utf8')).agentType || f; } catch {}
    }
    files.push({ label, file: path.join(subDir, f) });
  }
}

function scan(file) {
  const seen = new Map();
  const reads = [];
  let outChars = 0;
  for (const line of fs.readFileSync(file, 'utf8').split('\n')) {
    if (!line.trim()) continue;
    let j; try { j = JSON.parse(line); } catch { continue; }
    const m = j.message;
    if (j.type === 'assistant' && m?.id && m.usage) {
      seen.set(m.id, { u: m.usage, model: m.model });
      for (const c of m.content || []) {
        if (c.type === 'text') outChars += c.text.length;
        if (c.type === 'thinking') outChars += (c.thinking || '').length;
        if (c.type === 'tool_use') {
          outChars += JSON.stringify(c.input).length;
          const p = c.input?.file_path || c.input?.command || c.input?.pattern;
          reads.push(`${c.name}: ${String(p ?? JSON.stringify(c.input)).slice(0, 110)}`);
        }
      }
    }
  }
  const t = { calls: seen.size, in: 0, cw: 0, cr: 0, out: 0, model: '' };
  for (const { u, model } of seen.values()) {
    t.in += u.input_tokens || 0;
    t.cw += u.cache_creation_input_tokens || 0;
    t.cr += u.cache_read_input_tokens || 0;
    t.out += u.output_tokens || 0;
    t.model = model || t.model;
  }
  t.outEst = Math.round(outChars / 3);
  return { t, reads };
}

const showTools = process.argv.includes('--tools');
for (const { label, file } of files) {
  const { t, reads } = scan(file);
  console.log(`${label.padEnd(28)} ${t.model.padEnd(18)} calls=${t.calls} in=${t.in} cacheW=${t.cw} cacheR=${t.cr} out=${t.out} outEst=${t.outEst}`);
  if (showTools) reads.forEach((r) => console.log('   - ' + r));
}

