    if (existsSync(p)) return { path: p, source: 'profile', alias };
  }
  const root = resolveWorkspaceRoot(startDir);
  const legacy = join(root, '.sc4sap', 'sap.env');
  if (existsSync(legacy)) return { path: legacy, source: 'legacy', alias: null };
