 const ids=t=>new Set((t.match(/\b(?:Z[0-9A-Z_]{2,}|RV\d{2}[A-Z]\d{3}|[0-9]{3}\b(?=.*?)|[A-Z]{2,5}\d?[A-Z0-9]{0,4})\b/g)||[]).filter(x=>!/^(SAP|ECC|FI|MM|SD|CO|PP|WM|KR|THE|AND|OR|ID|HTML|PDF|URL|OK|NO|YES)$/.test(x)));
 const sb=ids(b), sv=ids(v);
 const onlyB=[...sb].filter(x=>!sv.has(x)), onlyV=[...sv].filter(x=>!sb.has(x));
 console.log('==',q,'chars base',b.length,'v2',v.length,'| ids base',sb.size,'v2',sv.size,'shared',[...sb].filter(x=>sv.has(x)).length);
 console.log(' only base:',onlyB.slice(0,60).join(' '));
 console.log(' only v2  :',onlyV.slice(0,60).join(' '));
 const z=t=>[...new Set(t.match(/\bZ[0-9A-Z_]{3,}\b/g)||[])]; console.log(' Z-objects base:',z(b).join(' '),'| v2:',z(v).join(' '));
}"

